namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        return await http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(customerEmail)}") ?? [];
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        await http.PutAsJsonAsync($"api/shipments/{id}/status", status);
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> Shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = new DateTime(2026, 7, 5), EstimatedDelivery = new DateTime(2026, 7, 14), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new() { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.OutForDelivery, ShippedDate = new DateTime(2026, 7, 1), EstimatedDelivery = new DateTime(2026, 7, 11), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new() { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, ShippedDate = new DateTime(2026, 7, 10), EstimatedDelivery = new DateTime(2026, 7, 20), CustomerEmail = "carol@example.com", Description = "Auto parts - 5 crates" },
        new() { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "São Paulo, BR", Destination = "Miami, US", Status = ShipmentStatus.Delivered, ShippedDate = new DateTime(2026, 6, 28), EstimatedDelivery = new DateTime(2026, 7, 8), CustomerEmail = "alice@example.com", Description = "Textiles - 3 rolls" },
        new() { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "Mumbai, IN", Destination = "Sydney, AU", Status = ShipmentStatus.Delayed, ShippedDate = new DateTime(2026, 7, 3), EstimatedDelivery = new DateTime(2026, 7, 18), CustomerEmail = "dave@example.com", Description = "Pharmaceuticals - temperature controlled" },
        new() { Id = 6, TrackingNumber = "TRK-006-2026", Origin = "Dubai, AE", Destination = "Paris, FR", Status = ShipmentStatus.PickedUp, ShippedDate = new DateTime(2026, 7, 9), EstimatedDelivery = new DateTime(2026, 7, 16), CustomerEmail = "bob@example.com", Description = "Machinery - 1 container" },
    ];

    private static readonly Lock Lock = new();

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (Lock)
        {
            return Task.FromResult(Shipments.ToList());
        }
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        lock (Lock)
        {
            var shipment = Shipments.FirstOrDefault(s =>
                s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        lock (Lock)
        {
            var results = Shipments
                .Where(s => s.CustomerEmail.Equals(customerEmail, StringComparison.OrdinalIgnoreCase))
                .ToList();
            return Task.FromResult(results);
        }
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        lock (Lock)
        {
            var shipment = Shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
            {
                shipment.Status = status;
            }
        }
        return Task.CompletedTask;
    }
}

