arguments.new_str:
// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Shipment API endpoints
app.MapGet("api/shipments", async (ShipmentServerService svc) =>
    await svc.GetAllShipmentsAsync())
    .RequireAuthorization();

app.MapGet("api/shipments/track/{trackingNumber}", async (string trackingNumber, ShipmentServerService svc) =>
{
    var shipment = await svc.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

app.MapGet("api/shipments/customer/{email}", async (string email, ShipmentServerService svc) =>
    await svc.GetShipmentsByCustomerAsync(email))
    .RequireAuthorization();

app.MapPut("api/shipments/{id}/status", async (int id, ShipmentStatus status, ShipmentServerService svc) =>
{
    await svc.UpdateShipmentStatusAsync(id, status);
    return Results.NoContent();
}).RequireAuthorization();

app.Run();

